(function(root){'use strict';const C=root.Critters,R=CritterRenderer.prototype,oldWorm=R.worm,event=R.event,projectile=R.projectile,weapon=R.weapon;
function costume(k,h,t=0){k.save();k.strokeStyle='#354859';k.lineWidth=2;const id=h.id;if(id==='bunny'){k.fillStyle='#ffe0eb';for(const x of [-8,9]){k.beginPath();k.ellipse(x,-12,5,17,x<0?-.18:.18,0,7);k.fill();k.stroke();k.fillStyle='#e99cbb';k.fillRect(x-1.5,-24,3,17);k.fillStyle='#ffe0eb';}}else if(id==='iron'){k.fillStyle='#527963';k.beginPath();k.ellipse(-14,20,14,20,-.5,0,7);k.fill();k.stroke();k.fillStyle='#8caa88';k.fillRect(-16,-13,32,10);k.strokeRect(-16,-13,32,10);}else if(id==='dragon'){k.fillStyle='#d75b62';for(const s of [-1,1]){k.beginPath();k.moveTo(s*6,-9);k.lineTo(s*17,-24);k.lineTo(s*16,-2);k.closePath();k.fill();k.stroke();}k.fillStyle='#e9886b';k.beginPath();k.moveTo(-15,21);k.lineTo(-34,4);k.lineTo(-27,30);k.lineTo(-12,37);k.fill();k.stroke();}else if(id==='guardian'){k.fillStyle='#7ea6be';k.fillRect(-16,-15,32,12);k.strokeRect(-16,-15,32,12);k.strokeStyle='#c4dce2';k.beginPath();k.moveTo(0,-15);k.lineTo(0,-26);k.stroke();k.fillStyle='#f9de8c';k.beginPath();k.arc(0,-29,4,0,7);k.fill();}else if(id==='twin'){k.fillStyle=h.color;for(const s of [-1,1]){k.beginPath();k.moveTo(s*3,-8);k.lineTo(s*15,-23);k.lineTo(s*18,-1);k.fill();k.stroke();}k.strokeStyle='#596079';for(const s of [-1,1])for(let j=0;j<2;j++){k.beginPath();k.moveTo(s*10,5+j*4);k.lineTo(s*25,2+j*10);k.stroke();}}else if(id==='ninja'){k.fillStyle='#24344d';k.fillRect(-15,-10,31,9);k.fillStyle='#d16d7b';k.beginPath();k.moveTo(-12,7);k.lineTo(-35,12+Math.sin(t*6)*4);k.lineTo(-23,20);k.lineTo(-10,15);k.fill();}else if(id==='medic'){k.fillStyle='#eef3d7';k.fillRect(-16,-16,32,14);k.strokeRect(-16,-16,32,14);k.fillStyle='#d27f7f';k.fillRect(-2,-14,4,10);k.fillRect(-6,-11,12,4);}k.restore();}
C.drawHeroPortrait=function(k,h,w=160,height=110){k.clearRect(0,0,w,height);k.save();k.translate(w/2,height*.62);k.scale(1.3,1.3);k.lineCap='round';k.lineJoin='round';k.strokeStyle='#344a54';k.lineWidth=23;k.beginPath();k.moveTo(-24,12);k.bezierCurveTo(-6,26,21,13,8,-2);k.lineTo(3,-17);k.stroke();k.strokeStyle=h.shade;k.lineWidth=19;k.stroke();k.strokeStyle=h.color;k.lineWidth=14;k.stroke();k.fillStyle=h.color;k.strokeStyle='#344a54';k.lineWidth=1.5;k.beginPath();k.ellipse(4,-22,16,14,0,0,7);k.fill();k.stroke();k.fillStyle='#fff8e5';for(const x of [-2,9]){k.beginPath();k.ellipse(x,-25,5,6,0,0,7);k.fill();k.fillStyle='#304353';k.beginPath();k.arc(x+1,-24,2,0,7);k.fill();k.fillStyle='#fff8e5';}k.strokeStyle='#805b59';k.beginPath();k.arc(8,-17,4,0,Math.PI);k.stroke();k.translate(4,-22);costume(k,h,0);k.restore();};
R.worm=function(k,u,...args){oldWorm.call(this,k,u,...args);const h=C.hero(u.character);if(h.id!=='scout'){k.save();k.translate(u.x,u.y);k.rotate(u.groundTilt||0);k.scale((u.face||1)*(args[0]||1),args[0]||1);k.translate(4,-25);costume(k,h,this.time);k.restore();}if(u.guardCharges>0||u.chilled){k.save();k.strokeStyle=u.chilled?'#b2e8ff':'#ffe597';k.lineWidth=2;k.setLineDash(u.chilled?[4,5]:[]);k.beginPath();k.ellipse(u.x,u.y-8,29,40,0,0,7);k.stroke();k.setLineDash([]);k.restore();}};
R.event=function(e){event.call(this,e);if(e.type==='volley'){root.PCSound?.fire(e.weapon);this.poses?.set(e.id,{recoil:1});}if(e.type==='guard'){this.rings.push({x:e.x,y:e.y,r:55,life:.5,max:.5});this.texts.push({x:e.x,y:e.y-70,text:'1회 방어!',life:1.2,color:'#ffe89d'});root.PCSound?.tone(950,.22,'triangle');}if(e.type==='doubleShot'){const u=this.game.units[e.id];this.texts.push({x:u.x,y:u.y-68,text:'2연발!',life:1.1,color:'#dec2ff'});}};
R.projectile=function(k){projectile.call(this,k);for(const p of [this.game.projectile,...(this.game.salvos||[])].filter(Boolean)){if(p.weapon<18)continue;const w=C.WEAPONS[p.weapon];k.save();k.translate(p.x,p.y);k.rotate(p.age*5);k.strokeStyle=w.color;k.fillStyle=w.color;k.lineWidth=2;if(w.id==='frost'){for(let i=0;i<6;i++){k.rotate(Math.PI/3);k.beginPath();k.moveTo(0,0);k.lineTo(0,-16);k.lineTo(-4,-11);k.moveTo(0,-16);k.lineTo(4,-11);k.stroke();}}else{k.beginPath();for(let i=0;i<10;i++){const a=i*Math.PI/5,r=i%2?7:17;k.lineTo(Math.cos(a)*r,Math.sin(a)*r);}k.closePath();k.fill();k.stroke();}k.restore();}};
R.weapon=function(k,id,x,y,s=1){if(id<18)return weapon.call(this,k,id,x,y,s);const w=C.WEAPONS[id];k.save();k.translate(x,y);k.scale(s,s);k.fillStyle=w.color;k.strokeStyle='#344657';k.lineWidth=2;k.beginPath();k.arc(0,0,18,0,7);k.fill();k.stroke();k.fillStyle='#243c50';k.font='bold 22px sans-serif';k.textAlign='center';k.textBaseline='middle';k.fillText(w.id==='frost'?'❄':w.id==='leech'?'♥':w.id==='orbital'?'↓':'✦',0,1);k.restore();};
})(globalThis);
